"use client";

import { useEffect, useRef, useState, type CSSProperties, type ReactNode } from "react";
import { createPortal } from "react-dom";
import {
  Bot as IconPopsicle2,
  Check as IconCheckmark1Small,
  ChevronDown as IconChevronDownSmall,
  Home as IconHome,
  LogOut as IconArrowBoxLeft,
  PanelLeftClose as IconSidebarLeftArrow,
  Plus as IconPlusMedium,
  Search as IconMagnifyingGlass,
  Settings as IconSettingsGear1,
  SquarePen as IconEditBig,
  UserPlus as IconUserAdd,
  X as IconCrossSmall,
} from "lucide-react";
import GlideMenu from "./GlideMenu";

/* ─────────────────────────────────────────────────────────
 * SIDEBAR NAV
 * Shared by the design-system preview and the harness shell:
 * compact workspace switcher, primary navigation, searchable
 * chat history, and a collapse that preserves icon alignment.
 * ───────────────────────────────────────────────────────── */

const WORKSPACE = { key: "fieldwork", name: "Fieldwork", monogram: "F" };

const NAV_ITEMS = [
  { key: "home", label: "Home", icon: <IconHome size={18} /> },
  { key: "invite", label: "Invite users", icon: <IconUserAdd size={18} />, count: "3/10" },
];

export type SidebarRecent = {
  id: string;
  label: string;
  prompt?: string;
};

const DEFAULT_RECENTS: SidebarRecent[] = [
  { id: "suppliers", label: "Supplier records" },
  { id: "todos", label: "Urgent to-dos this morning" },
  { id: "flavor", label: "Flavor page ticket" },
  { id: "workload", label: "Workload summary" },
  { id: "offboarding", label: "Off-board a supplier" },
  { id: "restock", label: "Batch restock function" },
  { id: "edits", label: "Propose flavor edits" },
  { id: "subway", label: "Subway surfing" },
];

type SidebarNavProps = {
  activeTitle?: string | null;
  className?: string;
  fill?: boolean;
  onNewChat?: () => void;
  onPick?: (id: string, label: string, prompt?: string) => void;
  /** controlled primary-nav selection (e.g. "home" | "invite") */
  activeNav?: string;
  onNavigate?: (key: string) => void;
  /** footer call-to-action — defaults to the demo "Upgrade" button */
  footerLabel?: string;
  footerIcon?: ReactNode;
  onFooterClick?: () => void;
  recents?: SidebarRecent[];
  variant?: string;
};

const SIDEBAR_MOTION = {
  expandedWidth: 224,
  collapsedWidth: 52,
  duration: 280,
  copyDuration: 180,
  copyOffset: 8,
  easing: "cubic-bezier(0.16, 1, 0.3, 1)",
};

/* ─────────────────────────────────────────────────────────
 * CHAT SEARCH STORYBOARD
 *
 *   0ms   search is triggered; Chats label begins fading
 *   0ms   field grows right → left from the search control
 * 180ms   field fills the row; cursor is focused and ready
 * ───────────────────────────────────────────────────────── */
const CHAT_SEARCH_MOTION = {
  duration: 180,
  closedWidth: 28,
  easing: "cubic-bezier(0.16, 1, 0.3, 1)",
};

function GlideGroup({ children }: { children: ReactNode }) {
  return (
    <GlideMenu
      rowSelector="[data-row]"
      highlightClassName="sidebar-glide-highlight rounded-[7px] bg-hover-2"
      className="group/glide flex flex-col gap-px"
    >
      {children}
    </GlideMenu>
  );
}

function RailButton({
  icon,
  label,
  active = false,
  count,
  onClick,
}: {
  icon: ReactNode;
  label: string;
  active?: boolean;
  count?: string;
  onClick?: () => void;
}) {
  return (
    <button
      data-row
      type="button"
      onClick={onClick}
      className={`sidebar-row relative z-10 mx-2 flex h-8 items-center rounded-[8px] px-2 text-left
        transition-[width,background-color,color,transform] duration-150 active:scale-[0.98]
        ${active ? "bg-hover-2 group-hover/glide:bg-transparent" : ""}`}
    >
      <span className={`flex size-5 shrink-0 items-center justify-center ${active ? "text-ink" : "text-ink-2"}`}>
        {icon}
      </span>
      <span className={`sidebar-copy ml-1.5 min-w-0 flex-1 truncate text-[14px] font-medium ${active ? "text-ink" : "text-ink-2"}`}>
        {label}
      </span>
      {count && (
        <span className="sidebar-copy mr-2 shrink-0 text-[12px] font-medium tabular-nums text-ink-3">
          {count}
        </span>
      )}
    </button>
  );
}

function WorkspaceMenu({
  position,
  onClose,
}: {
  position: { top: number; left: number };
  onClose: () => void;
}) {
  return createPortal(
    <div
      data-workspace-menu
      className="beautiful-ui-scope fixed z-50 w-64 rounded-[14px] bg-surface p-1.5 text-ink shadow-overlay"
      style={{
        top: position.top,
        left: position.left,
        animation: "beautiful-pop-in 180ms cubic-bezier(0.23,1,0.32,1) both",
        transformOrigin: "top left",
      }}
    >
      <GlideMenu className="flex flex-col gap-px" highlightClassName="inset-x-0 rounded-[8px] bg-hover-2">
        <button
          data-menu-row
          type="button"
          onClick={onClose}
          className="relative z-10 flex h-10 w-full items-center gap-1.5 rounded-[8px] px-2 text-left"
        >
          <span className="flex size-6 shrink-0 items-center justify-center rounded-[7px] bg-ink text-[11px] font-semibold text-surface">
            {WORKSPACE.monogram}
          </span>
          <span className="min-w-0 flex-1 truncate text-[13.5px] font-medium text-ink">{WORKSPACE.name}</span>
          <span className="shrink-0 text-ink"><IconCheckmark1Small size={18} /></span>
        </button>
        <div className="my-1 h-px bg-line" />
        {[
          { label: "New workspace", icon: <IconPlusMedium size={16} /> },
          { label: "Workspace settings", icon: <IconSettingsGear1 size={16} /> },
          { label: "Invite team members", icon: <IconUserAdd size={16} /> },
        ].map((item) => (
          <button
            key={item.label}
            data-menu-row
            type="button"
            onClick={onClose}
            className="relative z-10 flex h-9 w-full items-center gap-1.5 rounded-[8px] px-2 text-left"
          >
            <span className="flex size-5 shrink-0 items-center justify-center text-ink-2">{item.icon}</span>
            <span className="min-w-0 flex-1 truncate text-[13.5px] text-ink">{item.label}</span>
          </button>
        ))}
        <div className="my-1 h-px bg-line" />
        <button
          data-menu-row
          type="button"
          onClick={onClose}
          className="relative z-10 flex h-9 w-full items-center gap-1.5 rounded-[8px] px-2 text-left"
        >
          <span className="flex size-5 shrink-0 items-center justify-center text-ink-2"><IconArrowBoxLeft size={16} /></span>
          <span className="min-w-0 flex-1 truncate text-[13.5px] text-ink">Sign out</span>
        </button>
      </GlideMenu>
    </div>,
    document.body,
  );
}

export default function SidebarNav({
  activeTitle,
  className = "",
  fill = false,
  onNewChat,
  onPick,
  activeNav,
  onNavigate,
  footerLabel = "Upgrade",
  footerIcon,
  onFooterClick,
  recents = DEFAULT_RECENTS,
}: SidebarNavProps) {
  const [collapsed, setCollapsed] = useState(false);
  const [internalNav, setInternalNav] = useState("chats");
  const currentNav = activeNav ?? internalNav;
  const selectNav = (key: string) => {
    setInternalNav(key);
    onNavigate?.(key);
  };
  const [demoActiveTitle, setDemoActiveTitle] = useState<string | null>(null);
  const [workspaceOpen, setWorkspaceOpen] = useState(false);
  const [workspacePosition, setWorkspacePosition] = useState({ top: 0, left: 0 });
  const [searchOpen, setSearchOpen] = useState(false);
  const [query, setQuery] = useState("");
  const workspaceButtonRef = useRef<HTMLButtonElement>(null);
  const searchRef = useRef<HTMLInputElement>(null);

  const selectedTitle = activeTitle === undefined ? demoActiveTitle : activeTitle;
  const visibleRecents = recents.filter((item) => item.label.toLowerCase().includes(query.trim().toLowerCase()));

  useEffect(() => {
    if (!workspaceOpen) return;
    const close = (event: PointerEvent) => {
      const target = event.target as Element;
      if (!target.closest("[data-workspace-trigger]") && !target.closest("[data-workspace-menu]")) {
        setWorkspaceOpen(false);
      }
    };
    document.addEventListener("pointerdown", close);
    return () => document.removeEventListener("pointerdown", close);
  }, [workspaceOpen]);

  useEffect(() => {
    if (searchOpen) searchRef.current?.focus();
  }, [searchOpen]);

  const collapse = () => {
    setCollapsed(true);
    setWorkspaceOpen(false);
    setSearchOpen(false);
    setQuery("");
  };

  return (
    <aside
      data-sidebar-collapsed={collapsed}
      aria-label="Workspace navigation"
      className={`relative flex shrink-0 overflow-hidden transition-[width] ${fill ? "h-full" : "h-[600px]"} ${className}`}
      style={{
        width: collapsed ? SIDEBAR_MOTION.collapsedWidth : SIDEBAR_MOTION.expandedWidth,
        transitionDuration: `${SIDEBAR_MOTION.duration}ms`,
        transitionTimingFunction: SIDEBAR_MOTION.easing,
        "--sidebar-copy-duration": `${SIDEBAR_MOTION.copyDuration}ms`,
        "--sidebar-copy-offset": `${SIDEBAR_MOTION.copyOffset}px`,
        "--sidebar-easing": SIDEBAR_MOTION.easing,
      } as CSSProperties}
    >
      <div className="flex min-h-0 w-[224px] shrink-0 flex-col">
        <div className="relative mb-2.5 h-10 shrink-0">
          <button
            ref={workspaceButtonRef}
            data-workspace-trigger
            type="button"
            aria-expanded={workspaceOpen}
            aria-hidden={collapsed}
            tabIndex={collapsed ? -1 : 0}
            onClick={() => {
              if (!workspaceOpen && workspaceButtonRef.current) {
                const rect = workspaceButtonRef.current.getBoundingClientRect();
                setWorkspacePosition({ top: rect.bottom + 6, left: rect.left });
              }
              setWorkspaceOpen((open) => !open);
            }}
            className="sidebar-workspace-control absolute left-2 top-1 flex h-8 w-[164px] items-center rounded-[8px] px-2 text-left transition-[background-color,transform] duration-100 hover:bg-hover-2 active:scale-[0.99]"
          >
            <span className="sidebar-logo flex size-5 shrink-0 items-center justify-center text-ink">
              <IconPopsicle2 size={18} />
            </span>
            <span className="sidebar-copy ml-1.5 min-w-0 flex-1 truncate text-[14px] font-medium text-ink-2">
              {WORKSPACE.name}
            </span>
            <span className="sidebar-copy ml-1 flex shrink-0 text-ink-3">
              <IconChevronDownSmall size={16} />
            </span>
          </button>

          {workspaceOpen && <WorkspaceMenu position={workspacePosition} onClose={() => setWorkspaceOpen(false)} />}

          <button
            type="button"
            aria-label="Collapse sidebar"
            aria-hidden={collapsed}
            tabIndex={collapsed ? -1 : 0}
            onClick={collapse}
            className="sidebar-collapse-control absolute right-2 top-1 flex size-8 items-center justify-center rounded-[8px] text-ink-3 transition-[opacity,background-color,color] duration-150 hover:bg-hover-2 hover:text-ink"
          >
            <IconSidebarLeftArrow size={18} />
          </button>
          <button
            type="button"
            aria-label="Expand sidebar"
            aria-hidden={!collapsed}
            tabIndex={collapsed ? 0 : -1}
            onClick={() => setCollapsed(false)}
            className="sidebar-expand-control absolute left-2 top-0.5 flex size-9 items-center justify-center rounded-[8px] text-ink-3 transition-[opacity,background-color,color] duration-150 hover:bg-hover-2 hover:text-ink"
          >
            <IconSidebarLeftArrow size={18} className="rotate-180" />
          </button>
        </div>

        <GlideGroup>
          <RailButton
            icon={<IconEditBig size={18} />}
            label="New chat"
            onClick={() => {
              if (activeTitle === undefined) setDemoActiveTitle(null);
              selectNav("chats");
              onNewChat?.();
            }}
          />
          {NAV_ITEMS.map((item) => (
            <RailButton
              key={item.key}
              icon={item.icon}
              label={item.label}
              count={item.count}
              active={currentNav === item.key}
              onClick={() => selectNav(item.key)}
            />
          ))}
        </GlideGroup>

        <div className="mt-3 min-h-0 flex-1 overflow-y-auto">
          <div className="sidebar-copy relative mx-2 mb-1 h-8">
            <div
              aria-hidden={searchOpen}
              className={`absolute inset-0 flex items-center gap-1.5 px-2 text-[12.5px] font-medium text-ink-3 transition-[opacity,transform] ${searchOpen ? "pointer-events-none -translate-x-1 opacity-0" : "translate-x-0 opacity-100"}`}
              style={{ transitionDuration: `${CHAT_SEARCH_MOTION.duration}ms`, transitionTimingFunction: CHAT_SEARCH_MOTION.easing }}
            >
              <IconChevronDownSmall size={16} />
              <span>Chats</span>
            </div>

            <button
              type="button"
              aria-label="Search chats"
              aria-expanded={searchOpen}
              onClick={() => setSearchOpen(true)}
              className={`absolute right-0 top-0 z-10 flex size-8 items-center justify-center rounded-[8px] text-ink-3 transition-[opacity,background-color,color,transform] hover:bg-hover-2 hover:text-ink active:scale-[0.96] ${searchOpen ? "pointer-events-none opacity-0" : "opacity-100"}`}
              style={{ transitionDuration: `${CHAT_SEARCH_MOTION.duration}ms` }}
            >
              <IconMagnifyingGlass size={16} />
            </button>

            <div
              className={`absolute right-0 top-0 z-20 flex h-8 items-center overflow-hidden rounded-[8px] bg-field text-ink-3 shadow-hairline transition-[width,opacity] focus-within:text-ink-2 ${searchOpen ? "pointer-events-auto opacity-100" : "pointer-events-none opacity-0"}`}
              style={{
                width: searchOpen ? "100%" : CHAT_SEARCH_MOTION.closedWidth,
                transitionDuration: `${CHAT_SEARCH_MOTION.duration}ms`,
                transitionTimingFunction: CHAT_SEARCH_MOTION.easing,
              }}
            >
              <span className="ml-2 flex shrink-0 items-center justify-center">
                <IconMagnifyingGlass size={15} />
              </span>
              <input
                ref={searchRef}
                value={query}
                onChange={(event) => setQuery(event.target.value)}
                onKeyDown={(event) => {
                  if (event.key === "Escape") {
                    setSearchOpen(false);
                    setQuery("");
                  }
                }}
                placeholder="Search chats"
                aria-label="Search chat history"
                className="ml-1.5 min-w-0 flex-1 bg-transparent text-[13px] font-medium text-ink outline-none placeholder:text-ink-3"
              />
              <button
                type="button"
                aria-label="Close chat search"
                onClick={() => {
                  setSearchOpen(false);
                  setQuery("");
                }}
                className="flex size-8 shrink-0 items-center justify-center rounded-[8px] text-ink-3 transition-[background-color,color,transform] duration-150 hover:bg-hover-2 hover:text-ink active:scale-[0.96]"
              >
                <IconCrossSmall size={16} />
              </button>
            </div>
          </div>

          <GlideGroup>
            {visibleRecents.map((item) => {
              const active = item.label === selectedTitle;
              return (
                <button
                  key={item.id}
                  data-row
                  type="button"
                  title={item.label}
                  onClick={() => {
                    selectNav("chats");
                    if (activeTitle === undefined) setDemoActiveTitle(item.label);
                    onPick?.(item.id, item.label, item.prompt);
                  }}
                  className={`sidebar-row relative z-10 mx-2 flex h-8 items-center rounded-[8px] px-2 text-left transition-[width,background-color,color,transform] duration-150 active:scale-[0.98] ${
                    active ? "bg-hover-2 group-hover/glide:bg-transparent" : ""
                  }`}
                >
                  <span className={`sidebar-copy min-w-0 flex-1 truncate text-[14px] font-medium ${active ? "text-ink" : "text-ink-2"}`}>
                    {item.label}
                  </span>
                </button>
              );
            })}
            {query && visibleRecents.length === 0 && (
              <div className="sidebar-copy mx-2 px-2 py-2 text-[12.5px] text-ink-3">No chats found</div>
            )}
          </GlideGroup>
        </div>

        <div className="sidebar-copy mx-2 mt-3 w-[208px] border-t border-line pt-3">
          <button
            type="button"
            onClick={onFooterClick ?? onNewChat}
            className="flex h-8 w-full items-center justify-center gap-1.5 rounded-control bg-hover-2 text-[12.5px] font-medium text-ink transition-[background-color,transform] duration-150 hover:bg-line-strong active:scale-[0.98]"
          >
            {footerIcon}
            {footerLabel}
          </button>
        </div>
      </div>
    </aside>
  );
}

"use client";

import { useRef, useState, type ReactNode } from "react";

type GlideMenuProps = {
  children: ReactNode;
  className?: string;
  highlightClassName?: string;
  rowSelector?: string;
};

/** A single hover layer that glides between interactive menu rows. */
export default function GlideMenu({
  children,
  className = "",
  highlightClassName = "inset-x-0 rounded-[8px] bg-hover",
  rowSelector = "[data-menu-row]",
}: GlideMenuProps) {
  const ref = useRef<HTMLDivElement>(null);
  const [box, setBox] = useState<{ top: number; height: number } | null>(null);
  const [visible, setVisible] = useState(false);

  const moveTo = (target: EventTarget | null) => {
    const container = ref.current;
    if (!(target instanceof Element) || !container) return;
    const row = target.closest(rowSelector);
    if (!(row instanceof HTMLElement) || !container.contains(row)) return;
    const containerRect = container.getBoundingClientRect();
    const rowRect = row.getBoundingClientRect();
    setBox({ top: rowRect.top - containerRect.top, height: rowRect.height });
    setVisible(true);
  };

  return (
    <div
      ref={ref}
      onMouseOver={(event) => moveTo(event.target)}
      onMouseLeave={() => setVisible(false)}
      onFocusCapture={(event) => moveTo(event.target)}
      onBlurCapture={(event) => {
        if (!ref.current?.contains(event.relatedTarget as Node | null)) setVisible(false);
      }}
      className={`group/glide-menu relative ${className}`}
    >
      <span
        aria-hidden
        className={`pointer-events-none absolute ${highlightClassName}`}
        style={{
          top: box?.top ?? 0,
          height: box?.height ?? 0,
          opacity: box && visible ? 1 : 0,
          transition:
            "top 220ms cubic-bezier(0.23,1,0.32,1), height 220ms cubic-bezier(0.23,1,0.32,1), opacity 150ms ease",
        }}
      />
      {children}
    </div>
  );
}

/* GENERIC FOUNDATION — tokens, @theme, base rules, the primitive-*
 * spacing utilities, and shared keyframes below are needed by EVERY
 * component. Blocks tagged COMPONENT-SPECIFIC further down belong to
 * one primitive each. */
/* ──────────────────────────────────────────────────────────
 * Beautiful UI — design tokens
 * Cool near-white canvas, white cards, hairline borders, layered
 * single-digit-opacity shadows, a neutral ink ramp, and semantic
 * color used sparingly as a condiment.
 * ────────────────────────────────────────────────────────── */

.beautiful-ui-scope {
  /* surfaces — cool, blue-tinted neutrals */
  --page: oklch(0.985 0.001 286.376);
  --canvas: oklch(0.961 0.002 247.84);
  --surface: oklch(1 0 0);
  --inset: oklch(0.979 0.002 247.839);
  --hover: oklch(0.97 0.002 247.839);
  --hover-2: oklch(0.933 0.003 247.86);

  /* ink ramp */
  --ink: oklch(0.247 0.006 258.361);
  --ink-2: oklch(0.506 0.01 264.477);
  --ink-3: oklch(0.695 0.009 264.505);

  /* borders — solid and crisp, not alpha */
  --line: oklch(0.946 0.003 264.542);
  --line-strong: oklch(0.912 0.005 258.326);
  --line-soft: oklch(0.966 0.002 264.542);
  --grid-line: color-mix(in srgb, var(--line) 78%, transparent);
  --field: oklch(0.961 0.001 286.375);
  --stripe: oklch(0.405 0 0 / 0.075);
  --stripe-bg: oklch(0.97 0 0);

  /* accent */
  --accent: oklch(0.626 0.205 254.947);
  --accent-ink: oklch(0.556 0.187 255.617);
  --accent-tint: oklch(0.96 0.019 252.878);

  /* semantic */
  --green: oklch(0.603 0.155 150.883);
  --green-tint: oklch(0.958 0.017 159.118);
  --orange: oklch(0.689 0.179 49.902);
  --orange-tint: oklch(0.964 0.021 67.581);
  --red: oklch(0.621 0.192 23.042);
  --red-tint: oklch(0.956 0.017 17.462);

  /* chart overlays — neutral system colors with enough contrast on either theme */
  --tooltip-bg: oklch(0.272 0.008 264.435);
  --tooltip-fg: oklch(0.976 0.002 247.839);
  --tooltip-muted: oklch(0.731 0.008 260.731);
  --tooltip-border: oklch(0.356 0.007 264.474);

  /* shadows — our solid hairline ring + shadow-plugin's smooth layered stacks
   * (--shadow-xs…lg come from shadow-plugin/unprefixed) so every surface reads
   * consistently across the app. */
  --shadow-hairline: 0 0 0 1px var(--line);
  --shadow-xs: 0 0 4px 0 rgba(0, 0, 0, 0.04);
  --shadow-sm: 0 18px 47px 0 rgba(0, 0, 0, 0.03), 0 7.5px 19px 0 rgba(0, 0, 0, 0.02), 0 4px 10.5px 0 rgba(0, 0, 0, 0.02), 0 2.3px 5.8px 0 rgba(0, 0, 0, 0.01), 0 1.2px 3.1px 0 rgba(0, 0, 0, 0.01), 0 0.5px 1.3px 0 rgba(0, 0, 0, 0.01);
  --shadow-md: 0 17.54px 23.39px 0 rgba(0, 0, 0, 0.04), 0 9.4px 12.5px 0 rgba(0, 0, 0, 0.03), 0 5.25px 7px 0 rgba(0, 0, 0, 0.02), 0 2.79px 3.72px -2px rgba(0, 0, 0, 0.01), 0 1.16px 1.5px 0 rgba(0, 0, 0, 0.01);
  --shadow-lg: 0 25px 50px 0 rgba(0, 0, 0, 0.05), 0 12px 24px 0 rgba(0, 0, 0, 0.04), 0 6px 12px 0 rgba(0, 0, 0, 0.03), 0 3px 6px 0 rgba(0, 0, 0, 0.02), 0 1.5px 3px 0 rgba(0, 0, 0, 0.02);
  --shadow-btn: 0 0 0 1px var(--line-strong), var(--shadow-xs);
  --shadow-card: 0 0 0 1px var(--line), var(--shadow-sm);
  --shadow-raised: 0 0 0 1px var(--line), var(--shadow-md);
  --shadow-overlay: 0 0 0 1px var(--line), var(--shadow-lg);
  --shadow-inset-field: inset 0 1px 2px oklch(0 0 0 / 0.12);
}

.beautiful-ui-scope :is(button:not(:disabled), [role="button"]:not([aria-disabled="true"]), label:has(input), a) {
  cursor: pointer;
}

.beautiful-ui-scope :focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
  border-radius: 4px;
}

.beautiful-ui-scope :is(input, textarea, select, [contenteditable]):focus-visible {
  outline: none;
}

.dark .beautiful-ui-scope {
  --page: oklch(0.209 0.004 264.477);
  --canvas: oklch(0.231 0.004 264.487);
  --surface: oklch(0.26 0.006 271.191);
  --inset: oklch(0.243 0.004 264.492);
  --hover: oklch(0.289 0.006 271.22);
  --hover-2: oklch(0.318 0.007 274.747);

  --ink: oklch(0.964 0.002 247.839);
  --ink-2: oklch(0.731 0.008 260.731);
  --ink-3: oklch(0.541 0.01 264.484);

  --line: oklch(0.308 0.006 258.354);
  --line-strong: oklch(0.356 0.007 264.474);
  --line-soft: oklch(0.278 0.006 258.354);
  --field: oklch(0.293 0.006 271.223);
  --stripe: oklch(1 0 0 / 0.055);
  --stripe-bg: oklch(0.226 0.004 264.485);

  --accent: oklch(0.68 0.173 253.301);
  --accent-ink: oklch(0.788 0.113 248.33);
  --accent-tint: oklch(0.68 0.173 253.301 / 0.16);

  --green: oklch(0.705 0.154 153.814);
  --green-tint: oklch(0.705 0.154 153.814 / 0.14);
  --orange: oklch(0.746 0.156 55.642);
  --orange-tint: oklch(0.746 0.156 55.642 / 0.14);
  --red: oklch(0.666 0.18 21.433);
  --red-tint: oklch(0.666 0.18 21.433 / 0.14);

  --tooltip-bg: oklch(0.182 0.004 264.459);
  --tooltip-fg: oklch(0.964 0.002 247.839);
  --tooltip-muted: oklch(0.731 0.008 260.731);
  --tooltip-border: oklch(0.308 0.006 258.354);

  --shadow-hairline: 0 0 0 1px var(--line);
  /* Elevation rings go to a subtle *light* hairline in dark mode: the ring
   * paints over the surface behind the element, so a low-alpha white edge
   * dissolves into the shadow as one continuous stroke (per smooth-shadow-ring),
   * graduated by how far the surface floats. */
  --shadow-btn: 0 0 0 1px oklch(1 0 0 / 0.1), 0 1px 2px oklch(0 0 0 / 0.3);
  --shadow-card:
    0 0 0 1px oklch(1 0 0 / 0.11), 0 1px 2px oklch(0 0 0 / 0.2),
    0 2px 6px oklch(0 0 0 / 0.2);
  --shadow-raised:
    0 0 0 1px oklch(1 0 0 / 0.13), 0 2px 10px oklch(0 0 0 / 0.22);
  --shadow-overlay:
    0 0 0 1px oklch(1 0 0 / 0.15), 0 8px 28px oklch(0 0 0 / 0.34);
  --shadow-inset-field: inset 0 1px 2px oklch(0 0 0 / 0.4);
}

@theme inline {
  /* colors */
  --color-page: var(--page);
  --color-canvas: var(--canvas);
  --color-surface: var(--surface);
  --color-inset: var(--inset);
  --color-ink: var(--ink);
  --color-ink-2: var(--ink-2);
  --color-ink-3: var(--ink-3);
  --color-hover: var(--hover);
  --color-hover-2: var(--hover-2);
  --color-field: var(--field);
  --color-line: var(--line);
  --color-line-strong: var(--line-strong);
  --color-accent: var(--accent);
  --color-accent-ink: var(--accent-ink);
  --color-accent-tint: var(--accent-tint);
  --color-green: var(--green);
  --color-green-tint: var(--green-tint);
  --color-orange: var(--orange);
  --color-orange-tint: var(--orange-tint);
  --color-red: var(--red);
  --color-red-tint: var(--red-tint);

  /* shadows */
  --shadow-hairline: var(--shadow-hairline);
  --shadow-btn: var(--shadow-btn);
  --shadow-inset-field: var(--shadow-inset-field);
  --shadow-card: var(--shadow-card);
  --shadow-raised: var(--shadow-raised);
  --shadow-overlay: var(--shadow-overlay);

  /* type */
  --font-sans: var(--font-inter), ui-sans-serif, system-ui, sans-serif;
  --font-mono: var(--font-mono-face), ui-monospace, "SF Mono", monospace;

  /* radii — chips 6, controls 8, cards 10, windows 14, pills 999 */
  --radius-chip: 6px;
  --radius-control: 8px;
  --radius-card: 10px;
  --radius-window: 14px;

  /* easing — strong curves; built-ins are too weak */
  --ease-out-strong: cubic-bezier(0.23, 1, 0.32, 1);
  --ease-in-out-strong: cubic-bezier(0.77, 0, 0.175, 1);
  --ease-link: cubic-bezier(0.16, 1, 0.3, 1);
}

/* ══════════════════════════════════════════════════════════
 * COMPONENT-SPECIFIC — StreamingText / ContextCards
 * Favicon source avatars.
 * Copy this block only alongside StreamingText / ContextCards; it is not part of the
 * generic foundation above.
 * ══════════════════════════════════════════════════════════ */
.source-avatar {
  box-shadow: 0 0 0 1px oklch(0.21 0.034 263.436 / 0.1);
}

.dark .beautiful-ui-scope .source-avatar {
  box-shadow: 0 0 0 1px oklch(1 0 0 / 0.08);
}

/* ── primitive spacing system ─────────────────────────────
 * Shared optical offsets for small demo cards. Use these
 * instead of hand-tuning 10/12/14px per component.
 */

.primitive-card-pad {
  padding: 12px;
}

.primitive-card-bar {
  padding: 10px 12px;
}

.primitive-card-footer {
  padding: 10px;
}

.primitive-table-cell {
  padding: 10px 12px;
}

.primitive-icon-button {
  display: inline-flex;
  width: 28px;
  height: 28px;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-control);
}

/* ── shared keyframes ─────────────────────────────────── */

@keyframes beautiful-shimmer-text {
  from {
    background-position: 150% center;
  }
  to {
    background-position: -50% center;
  }
}

@keyframes beautiful-fade-up {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.home-reveal {
  will-change: opacity, transform, filter;
}

/* The sidebar is one persistent 224px tree clipped by a 52px shell.
 * Every rail glyph remains centered at x=26 in both states. */
/* ══════════════════════════════════════════════════════════
 * COMPONENT-SPECIFIC — SidebarNav
 * The 52↔224px collapsible sidebar tree.
 * Copy this block only alongside SidebarNav; it is not part of the
 * generic foundation above.
 * ══════════════════════════════════════════════════════════ */
.sidebar-row {
  width: 208px;
  transition-duration: var(--sidebar-copy-duration);
  transition-timing-function: var(--sidebar-easing);
}

.sidebar-copy {
  opacity: 1;
  transform: translateX(0);
  transition:
    opacity var(--sidebar-copy-duration) ease-out,
    transform var(--sidebar-copy-duration) var(--sidebar-easing);
}

.sidebar-logo,
.sidebar-collapse-control,
.sidebar-expand-control {
  transition-duration: var(--sidebar-copy-duration);
  transition-timing-function: ease-out;
}

.sidebar-expand-control {
  pointer-events: none;
  opacity: 0;
}

.sidebar-glide-highlight {
  right: 8px;
  left: 8px;
}

[data-sidebar-collapsed="true"] .sidebar-row {
  width: 36px;
}

[data-sidebar-collapsed="true"] .sidebar-copy {
  pointer-events: none;
  opacity: 0;
  transform: translateX(calc(var(--sidebar-copy-offset) * -1));
}

[data-sidebar-collapsed="true"] .sidebar-workspace-control {
  pointer-events: none;
}

[data-sidebar-collapsed="true"] .sidebar-logo,
[data-sidebar-collapsed="true"] .sidebar-collapse-control {
  pointer-events: none;
  opacity: 0;
}

[data-sidebar-collapsed="true"] .sidebar-expand-control {
  pointer-events: auto;
  opacity: 1;
}

[data-sidebar-collapsed="true"] .sidebar-glide-highlight {
  right: auto;
  width: 36px;
}

@media (prefers-reduced-motion: reduce) {
  .home-reveal {
    opacity: 1 !important;
    transform: none !important;
    filter: none !important;
  }
}

/* ── records table ────────────────────────────────────────
 * The grid is deliberately more architectural than card-like:
 * one quiet surface, precise rules, and color reserved for
 * meaning. The first column remains an anchor while both axes
 * can move independently inside the table viewport.
 */

/* ══════════════════════════════════════════════════════════
 * COMPONENT-SPECIFIC — RecordsTable
 * The full CRM grid, spreadsheet gutter, and AI column (~800 lines).
 * Copy this block only alongside RecordsTable; it is not part of the
 * generic foundation above.
 * ══════════════════════════════════════════════════════════ */
.records-shell {
  width: 100%;
  min-width: 0;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--surface);
  box-shadow: 0 1px 2px oklch(0 0 0 / 0.06);
}

/* fill mode: the shell stretches to fill its container and drops its own
 * border/radius/shadow so it reads as part of the surrounding card rather
 * than a container-in-a-container. The grid body flexes to fill height. */
.records-shell.is-fill {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
  height: 100%;
  border: 0;
  border-radius: 0;
  box-shadow: none;
}

.records-shell.is-fill .records-scroll {
  max-height: none;
  flex: 1;
}

.records-toolbar {
  display: flex;
  min-height: 52px;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 8px 10px;
  border-bottom: 1px solid var(--line-strong);
  background: var(--surface);
}

.records-toolbar-left,
.records-toolbar-right,
.records-company-header,
.records-quiet-button,
.records-secondary-button,
.records-primary-button,
.records-select-button,
.records-strength,
.records-link,
.records-add-calculation {
  display: inline-flex;
  align-items: center;
}

.records-toolbar-left,
.records-toolbar-right {
  gap: 4px;
}

.records-toolbar-right {
  flex-shrink: 0;
}

.records-select-button,
.records-quiet-button,
.records-secondary-button,
.records-primary-button {
  height: 32px;
  gap: 7px;
  border-radius: var(--radius-control);
  padding: 0 10px;
  font-size: 12px;
  font-weight: 500;
  white-space: nowrap;
  transition: background-color 140ms var(--ease-out-strong), color 140ms var(--ease-out-strong), transform 140ms var(--ease-out-strong), box-shadow 140ms var(--ease-out-strong);
}

.records-select-button {
  gap: 8px;
  color: var(--ink);
  border: 1px solid var(--line);
  background: var(--surface);
}

.records-select-button:hover,
.records-quiet-button:hover,
.records-secondary-button:hover {
  background: var(--hover);
  color: var(--ink);
}

.records-quiet-button {
  color: var(--ink-2);
}

.records-quiet-button.is-active {
  background: var(--accent-tint);
  color: var(--accent-ink);
}

.records-secondary-button {
  border: 1px solid var(--tooltip-border);
  color: var(--ink-2);
  box-shadow: none;
}

.records-primary-button {
  margin-left: 3px;
  background: var(--accent);
  color: oklch(1 0 0);
  box-shadow: none;
}

.records-primary-button:hover {
  filter: saturate(0.9) brightness(1.04);
}

.records-quiet-button:active,
.records-secondary-button:active,
.records-primary-button:active,
.records-select-button:active,
.records-add-calculation:active {
  transform: scale(0.96);
}

.records-database-icon {
  display: inline-flex;
  color: var(--green);
}

.records-filter-wrap {
  position: relative;
}

.records-filter-dot {
  width: 5px;
  height: 5px;
  margin-left: -2px;
  border-radius: 99px;
  background: var(--accent);
}

.records-filter-menu {
  position: absolute;
  z-index: 30;
  top: calc(100% + 7px);
  left: 0;
  width: 190px;
  padding: 6px;
  border: 1px solid var(--line-strong);
  border-radius: var(--radius-card);
  background: var(--surface);
  box-shadow: var(--shadow-overlay);
  animation: beautiful-pop-in 160ms var(--ease-out-strong) both;
  transform-origin: top left;
}

.records-sort-menu {
  left: -48px;
}

.records-filter-label {
  padding: 5px 8px 6px;
  color: var(--ink-3);
  font-size: 10.5px;
  font-weight: 500;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.records-filter-menu button {
  display: flex;
  width: 100%;
  align-items: center;
  gap: 7px;
  border-radius: var(--radius-chip);
  padding: 7px 8px;
  color: var(--ink-2);
  font-size: 12px;
  text-align: left;
  transition: background-color 120ms ease-out, color 120ms ease-out;
}

.records-filter-menu button:hover,
.records-filter-menu button.is-selected {
  background: var(--hover);
  color: var(--ink);
}

.records-menu-check {
  width: 13px;
  color: var(--accent-ink);
  font-size: 12px;
  font-weight: 500;
  text-align: center;
}

.records-scroll {
  max-height: 438px;
  overflow: auto;
  overscroll-behavior: none;
  scrollbar-color: var(--line-strong) transparent;
  scrollbar-gutter: stable;
}

.records-scroll:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: -2px;
}

.records-table {
  width: 100%;
  min-width: 990px;
  border-collapse: separate;
  border-spacing: 0;
  color: var(--ink);
  font-size: 13px;
  font-weight: 500;
  table-layout: fixed;
}

.records-company-col { width: 270px; }
.records-category-col { width: 275px; }
.records-last-col { width: 190px; }
.records-strength-col { width: 210px; }
.records-link-col { width: 175px; }

.records-table th,
.records-table td {
  border-right: 1px solid color-mix(in srgb, var(--line) 78%, transparent);
  border-bottom: 1px solid color-mix(in srgb, var(--line) 78%, transparent);
  text-align: left;
  vertical-align: middle;
}

.records-table tr > :last-child {
  border-right: 0;
}

.records-table thead th {
  position: sticky;
  z-index: 5;
  top: 0;
  height: 35px;
  background: var(--surface);
  color: var(--ink-2);
  font-size: 12.5px;
  font-weight: 500;
}

.records-header-cell {
  padding: 0;
}

.records-resize-handle {
  position: absolute;
  z-index: 12;
  top: 0;
  right: -6px;
  width: 12px;
  height: 100%;
  cursor: col-resize;
  touch-action: none;
}

.records-resize-handle::after {
  position: absolute;
  top: 7px;
  bottom: 7px;
  left: 5px;
  width: 2px;
  border-radius: 99px;
  background: var(--accent);
  content: "";
  opacity: 0;
  transform: scaleY(0.65);
  transition: opacity 120ms ease-out, transform 150ms var(--ease-out-strong);
}

.records-resize-handle:hover::after,
.records-resize-handle.is-resizing::after {
  opacity: 1;
  transform: scaleY(1);
}

.records-header-cell.records-sticky-cell {
  z-index: 7;
}

.records-header-button,
.records-company-header {
  width: 100%;
  height: 35px;
  gap: 8px;
  padding: 0 12px;
}

.records-company-header {
  padding-left: 6px;
}

.records-header-button {
  display: flex;
  align-items: center;
  color: var(--ink-2);
  text-align: left;
  transition: background-color 120ms ease-out, color 120ms ease-out;
}

.records-header-button:hover {
  background: var(--hover);
  color: var(--ink);
}

.records-header-icon {
  display: inline-flex;
  flex-shrink: 0;
  color: var(--ink-3);
}

.records-sort {
  display: inline-flex;
  flex-shrink: 0;
  margin-left: auto;
  opacity: 0;
  transition: opacity 120ms ease-out, transform 160ms var(--ease-out-strong);
}

.records-header-button:hover .records-sort,
.records-sort.is-visible {
  opacity: 1;
}

.records-company-header {
  display: flex;
}

.records-company-header > span:not(.records-checkbox-box) {
  white-space: nowrap;
}

.records-add-field {
  display: inline-flex;
  margin-left: auto;
  color: var(--ink-3);
  opacity: 0;
  transition: opacity 120ms ease-out, color 120ms ease-out;
}

.records-company-header:hover .records-add-field,
.records-add-field:focus-visible {
  opacity: 1;
}

.records-add-field:hover {
  color: var(--ink);
}

.records-checkbox {
  position: relative;
  display: inline-flex;
  width: 24px;
  height: 24px;
  flex: 0 0 24px;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-chip);
}

.records-checkbox input {
  position: absolute;
  width: 1px;
  height: 1px;
  opacity: 0;
}

.records-checkbox-box {
  display: inline-flex;
  width: 18px;
  height: 18px;
  align-items: center;
  justify-content: center;
  border: 1px solid oklch(0.845 0.011 247.953);
  border-radius: 6px;
  color: oklch(0.446 0.018 251.343);
  background: oklch(1 0 0);
  transition: border-color 140ms ease-out, background-color 140ms ease-out, box-shadow 140ms ease-out, transform 140ms var(--ease-out-strong);
}

.records-checkbox:hover .records-checkbox-box {
  border-color: oklch(0.773 0.016 251.194);
  background: oklch(0.966 0.003 228.784);
}

.records-checkbox:active .records-checkbox-box {
  transform: scale(0.96);
}

.records-checkbox input:focus-visible + .records-checkbox-box {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.records-checkbox-box.is-active {
  border-color: var(--accent);
  color: oklch(1 0 0);
  background: var(--accent);
  box-shadow: none;
}

.records-checkbox-dash {
  width: 8px;
  height: 1.5px;
  border-radius: 99px;
  background: oklch(1 0 0);
}

.dark .beautiful-ui-scope .records-checkbox-box {
  border-color: oklch(0.45 0.017 254.711);
  color: oklch(0.917 0.007 247.901);
  background: oklch(0.346 0.015 252.294);
}

.dark .beautiful-ui-scope .records-checkbox:hover .records-checkbox-box {
  border-color: oklch(0.521 0.019 254);
  background: oklch(0.391 0.016 251.761);
}

.dark .beautiful-ui-scope .records-checkbox-box.is-active {
  border-color: var(--accent);
  color: oklch(1 0 0);
  background: var(--accent);
}

.dark .beautiful-ui-scope .records-checkbox-dash {
  background: oklch(1 0 0);
}

.records-cell {
  height: 35px;
  padding: 0 8px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.records-sticky-cell {
  position: sticky;
  left: 0;
  z-index: 2;
  background: var(--surface);
  box-shadow: 5px 0 8px -10px oklch(0 0 0 / 0.4);
}

.records-company-cell {
  display: flex;
  align-items: center;
  gap: 4px;
  padding-left: 6px;
  overflow: visible;
}

.records-row > .records-cell {
  transition: background-color 120ms ease-out, color 120ms ease-out;
}

.records-row:hover > .records-cell {
  background: var(--hover);
}

.records-row.is-selected > .records-cell {
  background: color-mix(in srgb, var(--accent) 7%, var(--surface));
}

/* ── spreadsheet gutter ──────────────────────────────────
 * Row numbers at rest; the checkbox takes their place on
 * hover or once the row is selected. */
.records-rownum {
  display: inline-flex;
  width: 24px;
  height: 24px;
  flex: 0 0 24px;
  align-items: center;
  justify-content: center;
  color: var(--ink-3);
  font-size: 11.5px;
  font-variant-numeric: tabular-nums;
}

.records-row .records-checkbox {
  display: none;
}

.records-row:hover .records-rownum,
.records-row.is-selected .records-rownum {
  display: none;
}

.records-row:hover .records-checkbox,
.records-row.is-selected .records-checkbox {
  display: inline-flex;
}

/* ── selected column — the property being configured ───── */
.records-table th.is-colsel {
  background: color-mix(in srgb, var(--accent) 8%, var(--surface));
  box-shadow: inset 0 2px 0 var(--accent);
}

th.is-colsel .records-header-button,
th.is-colsel .records-company-header,
th.is-colsel .records-header-icon {
  color: var(--accent-ink);
}

.records-table td.is-colsel {
  background: color-mix(in srgb, var(--accent) 4%, var(--surface));
}

.records-row:hover > td.is-colsel {
  background: color-mix(in srgb, var(--accent) 8%, var(--surface));
}

.records-row.is-selected > td.is-colsel {
  background: color-mix(in srgb, var(--accent) 10%, var(--surface));
}

/* ── AI column calculating state ─────────────────────────── */
.records-calc {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.beautiful-records-pulse {
  width: 8px;
  height: 8px;
  flex: 0 0 8px;
  border-radius: 50%;
  background: var(--accent);
  animation: beautiful-records-pulse 1.1s ease-in-out infinite;
}

@keyframes beautiful-records-pulse {
  0%,
  100% {
    opacity: 0.35;
    transform: scale(0.8);
  }
  50% {
    opacity: 1;
    transform: scale(1);
  }
}

/* agent-screen — a static decorative cursor sitting on the capture (for show) */
.agent-cursor {
  position: absolute;
  pointer-events: none;
  filter: drop-shadow(0 1px 1.5px rgba(0, 0, 0, 0.35));
}

.records-company-mark {
  display: inline-flex;
  width: 20px;
  height: 20px;
  flex: 0 0 20px;
  align-items: center;
  justify-content: center;
  border: 0;
  border-radius: 6px;
  color: var(--ink-2);
  background: var(--field);
  font-size: 10px;
  font-weight: 500;
}

.records-company-name {
  min-width: 0;
  overflow: hidden;
  color: var(--ink);
  font-size: 13px;
  font-weight: 500;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.records-company-name.has-link:hover,
.records-company-name.has-link:focus-visible {
  color: var(--accent-ink);
  text-decoration: underline;
  text-underline-offset: 3px;
}

.records-tags {
  position: relative;
  display: flex;
  width: 100%;
  min-width: 0;
  align-items: center;
  gap: 4px;
  overflow: hidden;
}

.records-tags-measure {
  position: absolute;
  top: 0;
  left: 0;
  display: flex;
  width: max-content;
  gap: 4px;
  pointer-events: none;
  visibility: hidden;
}

.records-tags-measure > span {
  display: inline-flex;
}

.records-tag {
  display: inline-flex;
  height: 23px;
  max-width: 115px;
  align-items: center;
  flex-shrink: 0;
  overflow: hidden;
  cursor: pointer;
  border: 1px solid color-mix(in srgb, var(--tag-base) 32%, var(--surface));
  border-radius: 8px;
  padding: 0 7px;
  color: color-mix(in srgb, var(--tag-base) 92%, var(--ink));
  background: color-mix(in srgb, var(--tag-base) 18%, var(--surface));
  font-size: 13px;
  font-weight: 500;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.records-more-tag {
  display: inline-flex;
  height: 23px;
  align-items: center;
  flex-shrink: 0;
  border: 1px solid var(--line-strong);
  border-radius: 6px;
  padding: 0 7px;
  color: var(--ink-3);
  background: var(--inset);
  font-size: 11px;
  font-weight: 500;
}

.records-more-tag {
  border-color: var(--line-strong);
  color: var(--ink-3);
  background: var(--inset);
}

.records-muted {
  color: var(--ink-3);
}

.records-strength {
  gap: 8px;
  color: var(--ink-2);
}

.records-strength-dot {
  display: inline-block;
  width: 8px;
  height: 8px;
  flex: 0 0 8px;
  border-radius: 50%;
}

.records-link {
  max-width: 100%;
  gap: 5px;
  overflow: hidden;
  color: var(--accent-ink);
  text-overflow: ellipsis;
  text-decoration: underline;
  text-decoration-color: color-mix(in srgb, currentColor 35%, transparent);
  text-underline-offset: 3px;
  transition: color 120ms ease-out, text-decoration-color 120ms ease-out;
}

.records-link-label {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.records-link svg {
  flex-shrink: 0;
}

.records-link:hover,
.records-link:focus-visible {
  color: var(--ink);
  text-decoration-color: currentColor;
}

.records-table tfoot td {
  position: sticky;
  z-index: 4;
  bottom: 0;
  height: 35px;
  background: var(--inset);
  color: var(--ink-2);
  font-size: 14px;
  font-weight: 500;
  line-height: 1;
}

.records-table tfoot .records-sticky-cell {
  z-index: 6;
  background: var(--inset);
}

.records-calculation-label {
  color: var(--ink-2);
  font-weight: 500;
}

.records-footer-value {
  display: inline-flex;
  height: 35px;
  align-items: center;
  vertical-align: middle;
}

.records-calculation-number {
  margin-right: 3px;
  color: var(--ink);
  font-variant-numeric: tabular-nums;
}

.records-add-calculation {
  height: 35px;
  gap: 6px;
  color: var(--ink-3);
  font-size: 14px;
  font-weight: 500;
  line-height: 1;
  transition: color 120ms ease-out, transform 140ms var(--ease-out-strong);
}

.records-add-calculation:hover {
  color: var(--ink);
}

.records-average {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: var(--ink-2);
}

.records-calculation-row-secondary td {
  position: sticky;
  bottom: 35px;
  background: color-mix(in srgb, var(--inset) 70%, var(--surface));
}

.records-calculation-row-secondary .records-sticky-cell {
  position: sticky;
  background: color-mix(in srgb, var(--inset) 70%, var(--surface));
}

.records-footer {
  display: flex;
  min-height: 35px;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 0 12px;
  color: var(--ink-3);
  font-size: 11.5px;
}

.records-footer strong {
  color: var(--ink-2);
  font-weight: 500;
}

.records-footer-hint {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  opacity: 0;
  transition: opacity 160ms ease-out;
}

.records-shell:hover .records-footer-hint {
  opacity: 1;
}

.records-scroll-cue {
  display: inline-flex;
  color: var(--ink-3);
}

@media (max-width: 640px) {
  .records-toolbar {
    align-items: flex-start;
    flex-direction: column;
  }

  .records-toolbar-left,
  .records-toolbar-right {
    width: 100%;
  }

  .records-toolbar-right {
    justify-content: flex-end;
  }

  .records-footer-hint {
    display: none;
  }
}

/* ── filter table electric status colors ─────────────────── */

/* ══════════════════════════════════════════════════════════
 * COMPONENT-SPECIFIC — FilterTable
 * Electric status-pill colors.
 * Copy this block only alongside FilterTable; it is not part of the
 * generic foundation above.
 * ══════════════════════════════════════════════════════════ */
.filter-status-todo,
.filter-status-progress,
.filter-status-done {
  border: 1px solid transparent;
}

/* ══════════════════════════════════════════════════════════
 * COMPONENT-SPECIFIC — InsightCards
 * Liveline chart tooltip + cursor.
 * Copy this block only alongside InsightCards; it is not part of the
 * generic foundation above.
 * ══════════════════════════════════════════════════════════ */
.insight-chart-stage {
  overflow: hidden;
}

.insight-chart-cursor {
  position: absolute;
  z-index: 4;
  top: 0;
  bottom: 0;
  width: 1px;
  background: var(--ink);
  opacity: 0.26;
  pointer-events: none;
}

.insight-chart-tooltip-anchor {
  position: absolute;
  z-index: 5;
  top: 8px;
  transform: translateX(-50%);
  pointer-events: none;
}

.insight-chart-tooltip {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 5px 9px;
  border: 1px solid var(--line-strong);
  border-radius: 8px;
  color: var(--tooltip-fg);
  background: var(--tooltip-bg);
  box-shadow: var(--shadow-overlay);
  font-size: 11.5px;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.insight-chart-tooltip-item {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.insight-chart-tooltip-dot {
  width: 8px;
  height: 8px;
  flex: 0 0 8px;
  border-radius: 50%;
}

/* Status pills share the same base-hue → color-mix derivation as .records-tag,
 * so both components stay consistent across light and dark. */
.filter-status-todo {
  --tag-base: oklch(0.757 0.153 66.401);
}
.filter-status-progress {
  --tag-base: oklch(0.671 0.118 219.351);
}
.filter-status-done {
  --tag-base: oklch(0.652 0.131 162.865);
}

.filter-status-todo,
.filter-status-progress,
.filter-status-done {
  color: color-mix(in srgb, var(--tag-base) 92%, var(--ink));
  background: color-mix(in srgb, var(--tag-base) 20%, var(--surface));
  border-color: color-mix(in srgb, var(--tag-base) 34%, var(--surface));
}

/* Dark mode — a richer, saturated same-hue fill
 * with bright same-hue text and no visible border (light mode keeps the soft
 * tinted pastels above). Applies to both the records grid and status pills. */
.dark .beautiful-ui-scope .records-tag,
.dark .beautiful-ui-scope .filter-status-todo,
.dark .beautiful-ui-scope .filter-status-progress,
.dark .beautiful-ui-scope .filter-status-done {
  color: color-mix(in srgb, var(--tag-base) 86%, white);
  background: color-mix(in srgb, var(--tag-base) 34%, var(--surface));
  border-color: color-mix(in srgb, var(--tag-base) 34%, var(--surface));
}

@keyframes beautiful-fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes beautiful-eq-bounce {
  0%,
  100% {
    transform: scaleY(0.35);
  }
  50% {
    transform: scaleY(1);
  }
}

/* ── StreamText primitive ─────────────────────────────────
 * Fast character reveal: the newest few characters carry a
 * soft, masked blur so the leading edge resolves smoothly as
 * text flows in. The caret holds solid while streaming, then
 * blinks once the string settles. */
/* ══════════════════════════════════════════════════════════
 * COMPONENT-SPECIFIC — StreamText
 * The streaming caret + tail.
 * Copy this block only alongside StreamText; it is not part of the
 * generic foundation above.
 * ══════════════════════════════════════════════════════════ */
.stream-tail {
  filter: blur(1.6px);
  -webkit-mask-image: linear-gradient(to right, oklch(0 0 0) 20%, oklch(0 0 0 / 0.2));
  mask-image: linear-gradient(to right, oklch(0 0 0) 20%, oklch(0 0 0 / 0.2));
}

.stream-caret {
  display: inline-block;
  width: 2px;
  height: 1.05em;
  margin-left: 1.5px;
  translate: 0 -0.5px;
  border-radius: 1px;
  background: var(--ink);
  vertical-align: text-bottom;
  animation: beautiful-caret-blink 1s step-end infinite;
}

.stream-caret.is-streaming {
  animation: none;
}

@keyframes beautiful-caret-blink {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  .stream-caret {
    animation: none;
  }
  .stream-tail {
    filter: none;
    -webkit-mask-image: none;
    mask-image: none;
  }
}

@keyframes beautiful-pop-in {
  from {
    opacity: 0;
    transform: scale(0.95);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

@keyframes beautiful-spin {
  to {
    transform: rotate(360deg);
  }
}

/* pixel-grid loader — brighten plateau, staggered per cell */
@keyframes beautiful-pixel-on {
  0%, 100% {
    opacity: 0.15;
  }
  18%, 42% {
    opacity: 1;
  }
  62% {
    opacity: 0.15;
  }
}

@media (prefers-reduced-motion: reduce) {
  .beautiful-ui-scope *,
  .beautiful-ui-scope *::before,
  .beautiful-ui-scope *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}
